export const CATEGORIES = [...new Set(DATA.map((d) => d.type))].sort();

// borough centroids, computed from the real sample, for manual location picking
export const BOROUGH_CENTROIDS = (() => {
  const groups = {};
  DATA.forEach((d) => {
    if (!groups[d.borough]) groups[d.borough] = { lat: 0, lng: 0, n: 0 };
    groups[d.borough].lat += d.lat;
    groups[d.borough].lng += d.lng;
    groups[d.borough].n += 1;
  });
  return Object.entries(groups)
    .map(([name, g]) => ({ name, lat: g.lat / g.n, lng: g.lng / g.n }))
    .sort((a, b) => a.name.localeCompare(b.name));
})();
